public interface IErrorLogger
{
    void Log(string message);
}

public class ErrorLogger : IErrorLogger
{
    public void Log(string message) => Console.WriteLine($"ERROR: {message}");
}

public class LogExceptionFilter : IExceptionFilter
{
    private readonly IErrorLogger _logger;

    public LogExceptionFilter(IErrorLogger logger)
    {
        _logger = logger;
    }

    public void OnException(ExceptionContext context)
    {
        _logger.Log(context.Exception.Message);
        context.Result = new ContentResult
        {
            Content = "An error occurred. Please try again later.",
            StatusCode = 500
        };
        context.ExceptionHandled = true;
    }
}

// In the controller:
[TypeFilter(typeof(LogExceptionFilter))]
public IActionResult RiskyOperation()
{
    throw new InvalidOperationException("Something went wrong");
}

